mapper.select:
SELECT


FROM railway_lines

WHERE 1 = 1


  AND (
  LOCATE(TRIM(#{query.keyword}), name) > 0
  OR LOCATE(TRIM(#{query.keyword}), name_kana) > 0
  )



  AND operator_source_code = #{query.operatorSourceCode}



  AND status = #{query.status}


ORDER BY sort_order ASC, id ASC

mapper.update:
UPDATE railway_lines
SET name = #{line.name}, name_kana = #{line.nameKana}, color = #{line.color}, sort_order = #{line.sortOrder}, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{line.id}

UPDATE railway_lines
SET status = #{status}, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{lineId}

UPDATE stations
SET line_name = #{name}, updated_at = UTC_TIMESTAMP(3)
WHERE line_id = #{lineId}
